mapper.select:
SELECT COUNT(*)
FROM member_report mr
JOIN report_case rc ON rc.case_id = mr.case_id
WHERE mr.reporter_id = #{reporterId}
  AND rc.report_type = #{reportType}
  AND rc.target_id = #{targetId}

SELECT case_id
FROM report_case
WHERE report_type = #{reportType}
  AND target_id = #{targetId}
  AND status = #{status}
ORDER BY case_id DESC
LIMIT 1
FOR UPDATE
